theorem section_point {R : Type} [CommRing R] (c : R) :
    let a := 3*(c-1)^2
    let b := (3*c+1)*(c+3)
    let d := (c-1)*(c+3)
    d*(d+a)*(d+b) = (4*c*d)^2 := by

theorem double_numerator {R : Type} [CommRing R] (c : R) :
    let a := 3*(c-1)^2
    let b := (3*c+1)*(c+3)
    let d := (c-1)*(c+3)
    d^2-a*b = -8*c*d*(c-1) := by

def ExtraBitLift {G A} [Mul G] [IntModule A] (act : PointAction G A)
    (m : Nat) (P : A) (V : G → A) : Prop :=
  ∀ g, (2^(m+1) : Nat) • V g = (act.map g).apply P - P

theorem doubled_lift_multiple {G A} [Mul G] [IntModule A] {act : PointAction G A}
    {m : Nat} {P : A} {V : G → A} (hV : ExtraBitLift act m P V) (g : G) :
    (2^m : Nat) • ((2 : Nat) • V g) = (act.map g).apply P - P := by

theorem fifth_power {R : Type} [CommRing R] (r k : R) :
    let z := r^2*(r+k)
    z*r^2-k*z*r+k^2*z-k^3*r^2 = r^5 := by dsimp; grobner

