private theorem origin_parity (n : Nat) (f : List Bool → Bool)
    (hf : ∀ w, w.length = n → w ≠ List.replicate n false → f w = false) :
    parity n f = f (List.replicate n false) := by

theorem contact_gates {R : Type} [CommRing R] (b : R) :
    let u := b*(b-1)
    let v := u*(32*u-76457*b-823543)
    (2*b-1)*v = b*(b-1)*(b-2401)*(32*b+343)*(2*b-1) := by dsimp; grobner

theorem involution {R : Type} [CommRing R] (β l a b : R) :
    let u := b-β*l*a
    let v := β*(3*a+l*b)
    let h := β*(3+β*l^2)
    v-β*l*u=h*a ∧ β*(3*u+l*v)=h*b := by

theorem pencil_similitudes {R : Type} [CommRing R] (β l a b : R) :
    let u := b-β*l*a
    let v := β*(3*a+l*b)
    let h := β*(3+β*l^2)
    v^2+3*β*u^2=h*(b^2+3*β*a^2) ∧
    (v+β*l*u)^2+3*β*(u+l*v)^2=h*((b+β*l*a)^2+3*β*(a+l*b)^2) := by

theorem canonical_section {R : Type} [CommRing R] (β j : R) :
    let k := β*j^2
    let n := β*(k-1)*(k-9)
    let x := β*(k+3)^2
    let y := 8*β^2*j*(k+3)*(k-3)
    x-n = (4*β*j)^2 ∧ x+3*n = β*(2*(k-3))^2 ∧ y^2 = x*(x-n)*(x+3*n) := by

def Surface (A H : Rat) : Prop :=
  H ≠ 0 ∧ ∃ u₁ v₁ u₂ v₂ W : Rat, W ≠ 0 ∧
    quartic A u₁ v₁ * quartic A u₂ v₂ = H*W^2

private def Coupled (A H : Rat) : Prop :=
  H ≠ 0 ∧ ∃ c₁ p₁ c₂ p₂ z : Rat, c₁ ≠ 0 ∧ c₂ ≠ 0 ∧ z ≠ 0 ∧
    Conic A c₁ p₁ ∧ Conic A c₂ p₂ ∧ H*c₁ = c₂*z^2

private theorem scaled (A s c p e r : Rat) (hs : s ≠ 0)
