def rootsCoeff (r : Fin 6 → ℂ) : ℕ → ℂ :=
  let a := -(r 0*r 1*r 2)
  let b := r 0*r 1+r 0*r 2+r 1*r 2
  let c := -(r 0+r 1+r 2)
  let d := -(r 3*r 4*r 5)
  let e := r 3*r 4+r 3*r 5+r 4*r 5
  let g := -(r 3+r 4+r 5)
  fun
    | 0 => a*d
    | 1 => b*d+a*e
    | 2 => c*d+b*e+a*g
    | 3 => d+c*e+b*g+a
    | 4 => e+c*g+b
    | 5 => g+c
    | 6 => 1
    | _ => 0

