def TwistPoint (β l : ℕ) : Prop :=
  ∃ t y : ℚ, t≠0 ∧
    (let x := (β:ℚ)*t^2; y^2=x*(x-l)*(x+3*l))

private theorem lift_root {p : ℕ} [Fact p.Prime] (hp : p≠2) {A r D : ℤ}
