    ∃ t : ℤ, ¬(p:ℤ)∣t ∧ D*(p:ℤ)∣A-t^2 := by

def functionBranch (μ B e z : RatFunc ℚ) : Prop :=
  let a:=μ*B
  let H:=a*(a-B^2)
  a*e*H*z≠0 ∧ ∃ y w : RatFunc ℚ,
    y^2=a*(a-e)*(a+3*e) ∧ w^2=a*(a*z^2-e*H)*(a*z^2+3*(e*H))

private theorem zero_twist {b l u : ℚ} (bn : b≠0) (un : u≠0)
    (e : (0:ℚ)^2=(b*u^2)*(b*u^2-l)*(b*u^2+3*l)) :
    ∃ r : ℚ,r≠0 ∧ (l=b*r^2 ∨ l=(-3*b)*r^2) := by

theorem root_of_ray {p : ℕ} (pp : p.Prime) {z : Gaussian}
    (hz : gaussianNorm z=p) (h16 : gaussianCongruent 16 z (9,0))
