def crossing (A : Fin 3→ℚ) (K L : ℕ) (x : ℕ×ℕ) : Prop :=
  ∀ q : ℕ, q.Prime → K<q → q≤L →
    if q%4=3 then ¬((x.1:ZMod q)=1 ∧ (x.2:ZMod q)=0)
    else (∀ i : ↥(shifts A), ¬(q:ℤ)∣signedOrder (form A x i).toNat true) ∨
         (∀ i : ↥(shifts A), ¬(q:ℤ)∣signedOrder (form A x i).toNat false)

theorem crossing_iff {A : Fin 3→ℚ} {K L : ℕ} {x : ℕ×ℕ}
    (base : ∀ i : ↥(shifts A),commonPrime K K (form A x i).toNat) :
    crossing A K L x ↔ extraTest A K L x := by

def coefficientBase (n t : ℤ) : Prop :=
  n≡1 [ZMOD 8] ∧ n≡3 [ZMOD 7] ∧ orient t≡18 [ZMOD 32] ∧ orient t≡2 [ZMOD 14] ∧
  4*n≡t^2 [ZMOD 1024]

theorem coefficient_periodic {L : ℕ} {n n' t t' : ℤ}
    (hn : n≡n' [ZMOD modulus L]) (ht : t≡t' [ZMOD modulus L]) :
    coefficientClass L n t ↔ coefficientClass L n' t' := by

theorem order_periodic {L q : ℕ} (prime : q.Prime) (small : q≤L) {n n' t t' : ℤ}
    (hn : n≡n' [ZMOD modulus L]) (ht : t≡t' [ZMOD modulus L]) (s : Bool) :
    coefficientOrder n t s ≡ coefficientOrder n' t' s [ZMOD q] := by

def expansion {P : Type*} [Fintype P] (safe : P→Bool→ι→Prop) : Prop :=
    (∏ q,if (∀ i,safe q true i) ∨ (∀ i,safe q false i) then (1:ℕ) else 0)=
    ∑ r : P→Option ι, ∏ i,∏ q, if rectangle (safe q) (r q) i then 1 else 0

def baseRay (p : ℕ) : Prop :=
  p%8=1 ∧ p%7=3 ∧ root p ≡ 9 [ZMOD 16] ∧ root p ≡ 1 [ZMOD 7] ∧
  (p:ℤ) ≡ (root p)^2 [ZMOD 256]

def inertRate (c : ι → ZMod p) : ℝ :=
  (∑ w : ZMod p, ∑ u : ZMod p,
    if (∀ i, norms c u w i ≠ 0) ∧ ¬ (u=1 ∧ w=0) then (1:ℝ) else 0) / (p:ℝ)^2

def extraTest (A : Fin 3→ℚ) (K L : ℕ) (q : ℕ×ℕ) : Prop :=
  ∃ π : ↥(shifts A) → Gaussian,
    (∀ i, gaussianNorm (π i)=(form A q i).toNat ∧
      gaussianCongruent 16 (π i) (9,0) ∧ gaussianCongruent 7 (π i) (1,3)) ∧
    ∀ p : ℕ,p.Prime → K<p → p≤L →
      if p%4=3 then ¬((q.1 : ZMod p)=1 ∧ (q.2 : ZMod p)=0)
      else (∀ i,¬p∣adjacentNorm (π i) true) ∨ (∀ i,¬p∣adjacentNorm (π i) false)

def hybrid {A : Fin 3→ℚ} {d : ℕ} {H Y : ℝ}
    (a : Candidate A d H Y) (T : Finset ℕ) (κ K L : ℕ) : Prop :=
  below a T κ K ∧ ∀ q : ℕ, q.Prime → K<q → q≤L →
    if q%4=3 then ¬((a.u:ZMod q)=1 ∧ (a.v:ZMod q)=0)
    else atPrime a.gaussian T κ q

def hybridLoss (A : Fin 3→ℚ) (q : ℕ) : ℝ :=
  if hp : q.Prime then
    let _ : Fact q.Prime := ⟨hp⟩
    if q%4=3 then 1-inertRate (coefficients A q)/unitRate (coefficients A q)
    else markedLoss A q
  else 0

private theorem dyadic (L n : ℕ) (pos : 0 < L) :
    (∑ p ∈ places L (2^n*L), Real.log p / (p : ℝ)^2) ≤
      4*Real.log 4 * (1/(L:ℝ) - 1/((2^n*L : ℕ) : ℝ)) := by

def IntegralFibre (b θ n m : ℤ) : Prop := ∃ U V Y : ℤ,
  U.natAbs.Coprime V.natAbs ∧ U^2-b*V^2≠0 ∧
  Y^2=b*leftForm b (n^2) (θ*m^2) U V * rightForm b (n^2) (θ*m^2) U V

def cube (r : ℕ) : Finset (Point ℤ) :=
