def Narrow (S : ℕ → Prop) : Prop :=
  ∀ (coeff : Finset ℤ) (Y : ℕ), ∃ u>Y, ∃ m : ℕ, 0 < m ∧ m^4≤u ∧
    ∀ h∈coeff, ∃ p : ℕ, (p:ℤ)=(u:ℤ)+h*(m:ℤ)^2 ∧ S p

def PositivePrimeDensity (S : ℕ → Prop) : Prop :=
  ∃ δ : ℝ, 0<δ ∧ ∃ N₀ : ℕ, ∀ N≥N₀,
    δ * (Nat.primeCounting N : ℝ) ≤ (((Finset.range (N+1)).filter (fun n=>S n)).card:ℝ)

def RayCountEstimates (K : ℕ) : Prop :=
  ∃ c : ℝ, 0<c ∧ ∃ t₀ : ℕ, ∀ t≥t₀,
    let R:=2^t
    let N:=2^(8*t)
    let B:=c * (Nat.primeCounting N : ℝ)
    (15/16)*B ≤ ((primeBase K N).card:ℝ) ∧
    ∑ q∈splitPlaces K R, |((selfAt K N q).card:ℝ)-B*(2/((q:ℝ)-1)^2)| ≤ B/16

def PrimeGrowth : Prop :=
  (∀ c : ℝ, 0<c → ∃ t₀ : ℕ, ∀ t≥t₀,
    let N:=2^(8*t)
    (2*(N.sqrt:ℝ)+1)*(Nat.log 2 (N.sqrt^2+1):ℝ)*((2*(N.sqrt:ℝ)+1)/(2^t:ℕ)+1)
      ≤ c * (Nat.primeCounting N:ℝ)) ∧
  ∃ t₀ : ℕ, ∀ t≥t₀, Nat.primeCounting (2^(8*(t+1))) ≤ 512 * Nat.primeCounting (2^(8*t))

def rayGenerator (K : ℕ) (z : Gaussian) : Prop :=
  gaussianCongruent 16 z (9,0) ∧ gaussianCongruent 7 z (1,3) ∧
    ∀ q, q.Prime → q≠2 → q≠7 → q≤K → gaussianCongruent q z (0,1)

def selfAt (K N q : ℕ) : Finset ℕ :=
