def Recurrent (c : Finset ℤ) (s B : ℕ) : Prop :=
  ∀ S : Finset (Fin B), B ≤ 2*s*S.card →
    ∃ a : Fin B, ∃ m ∈ Icc 1 B, ∀ h ∈ c, ∃ b ∈ S, (b.val:ℤ) = a.val + h*m^2

theorem good_card (E : Finset (ZMod n)) (D : ZMod n) {s B : ℕ}
