def mixedMass (c D : Finset ℤ) (f g : ZMod n → ℝ) (H : ZMod n) (M : ℕ) : ℝ :=
  ∑ p ∈ (Icc 1 M ×ˢ (univ : Finset (ZMod n))),
    ∏ h ∈ c, (if h∈D then g else f) (p.2+H*(h:ZMod n)*(p.1:ZMod n)^2)

def OnePrimeDensity : Prop :=
  ∀ K : ℕ, ∃ η : ℝ, 0<η ∧ ∀ V : ℕ, 0<V → ∀ᶠ N : ℕ in atTop,
    η*N ≤ ∑ p∈band N V,classWeight K p

def window (K b V N : ℕ) (x : ZMod n) : ℝ :=
  if N/2 < b+V*x.val ∧ b+V*x.val ≤ N ∧ n ≤ 4*x.val ∧ 4*x.val < 3*n
  then classWeight K (b+V*x.val) else 0

def NarrowClassRecurrence : Prop :=
  ∀ (K : ℕ) (c : Finset ℤ) (Y : ℕ), ∃ u > Y, ∃ m : ℕ, 0 < m ∧ m^4 ≤ u ∧
    ∀ h∈c, ∃ p:ℕ, (p:ℤ)=(u:ℤ)+h*(m:ℤ)^2 ∧ oneClass K p

def circleMass (c : Finset ℤ) (g : ZMod n → ℝ) (H : ZMod n) (W : ℕ) : ℝ :=
  ∑ p ∈ (Icc 1 W ×ˢ (univ : Finset (ZMod n))),
    ∏ h ∈ c, g (p.2 + H * (h:ZMod n) * (p.1:ZMod n)^2)

