private theorem odd_contactPoly_iff {p : ℕ} (hp : p.Prime) (large : 61 < p)
    {t : ℚ} (ht : t ∉ contactSet) :
    Odd (padicValRat p (Mult.contactPoly t)) ↔ Mult.IsOddContactPrime t p := by

private theorem primeProduct_dvd {bad : Finset ℕ} {n : ℕ}
    (primes : ∀ p ∈ bad, p.Prime) (each : ∀ p ∈ bad, p ∣ n) :
    (∏ p ∈ bad, p) ∣ n := by

noncomputable def vonKanelBound (g : ℕ) (bad : Finset ℕ) : ℝ :=
  let v := (vonKanelParameter g bad : ℝ)
  (g : ℝ) * (18000 * v^12 + (8*(g : ℝ))^6 * Real.log v)

private theorem slope_bound {m : ℕ} (height : UniformHeight (m : ℝ)) (n : Fin 3 → ℤ)
    (hf : n 0 * n 1 - n 2 ≠ 0) {t : ℚ}
    (slope : Mult.SlopePred t (Syntax.ell : ℚ) (Mult.certShifts n)) :
    ratHeight t ≤ (m : ℝ) * |((n 0 * n 1 - n 2 : ℤ) : ℝ)| ^ ((24 : ℝ) / 25) := by

private theorem BracketTerm.filter_eq {d : ℕ} (hd : d % 8 = 5) (T : BracketTerm d) :
    (T.factors.filter fun a => a % 8 = 7) = {T.d₀} ∧
    (T.factors.filter fun a => a % 8 = 3) = {T.d₁} := by

private theorem unique_owner {d p a b : ℕ} {F : Finset ℕ} (hs : Squarefree d)
    (hp : p.Prime) (hprod : ∏ t ∈ F, t = d)
    (ha : a ∈ F) (hb : b ∈ F) (hpa : p ∣ a) (hpb : p ∣ b) : a = b := by

private def component (X : Over (Spec (.of K))) (σ : Ω ≃ₐ[K] Ω) :
    (F).obj X ≅ (G σ).obj ((F).obj X) := by
  let A := (F).obj X
  let f : A.left ⟶ pullback A.hom (S σ) := pullback.lift (deck X.hom σ) A.hom (deck_snd X.hom σ)
  let : IsIso (deck X.hom σ) := ⟨deck X.hom σ.symm, deck_inverse X σ, deck_inverse X σ.symm⟩
  let : IsIso (S σ) := inferInstanceAs (IsIso ((Scheme.Spec.mapIso σ.toRingEquiv.toCommRingCatIso.op).hom))
  let : IsIso f := IsIso.of_isIso_fac_right (show f ≫ pullback.fst A.hom (S σ) = deck X.hom σ from pullback.lift_fst ..)
  exact Over.isoMk (asIso f) (pullback.lift_snd ..)

private def rationalGroupComparison (A : GroupScheme K) (σ : Ω ≃ₐ[K] Ω) :
    (F).mapCommGrp.obj A ≅ (G σ).mapCommGrp.obj ((F).mapCommGrp.obj A) :=
  (Functor.mapCommGrpNatIso (rationalComparison σ)).app A ≪≫ Functor.mapCommGrpCompIso.app A

private def residueEquiv : ResidueField (WittVector p k) ≃+* k :=
  (Ideal.quotEquivOfEq (show maximalIdeal (WittVector p k) = Ideal.span {(p : WittVector p k)}
    from (WittVector.irreducible p).maximalIdeal_eq)).trans WittVector.quotientPEquiv

theorem configuration_two {R : Type*} [CommRing R] [IsLocalRing R] {f : R[X]} {c : R}
    {a : Fin 2 → R} {ξ : Fin 2 → Fin 3 → ResidueField R} (T : TwoTriples f a c ξ) :
    Nonempty (Configuration f Finset.univ c) := by

theorem configuration_one {R : Type*} [CommRing R] [IsLocalRing R] {u V : R}
    (T : ZeroFibreRoots u V) (hu : residue R u = 0) :
    Nonempty (Configuration (sextic (u^6) V) {0} (u^2)) := by

def principal (A : Finset (Fin 2)) (s : Cluster) : Prop :=
  s ∈ tree A ∧ 3 ≤ s.card ∧ ¬(s=Finset.univ ∧ Even s.card ∧ (children A s).card=2) ∧
    ∀ t ∈ children A s, t.card ≠ 4

theorem configuration_exhausts {R : Type*} [CommRing R] [IsDomain R] {f : R[X]} {A : Finset (Fin 2)}
    {c : R} (T : Configuration f A c) (hc : c ≠ 0) (hd : f.natDegree = 6) :
    f.roots.Nodup ∧ f.Splits ∧ ∀ w, f.IsRoot w ↔ ∃ i, T.point i=w := by

private def strictResidue : ResidueField W ≃+* Residues p :=
  (Ideal.quotEquivOfEq (show IsLocalRing.maximalIdeal W = Ideal.span {(p : W)} from
    (WittVector.irreducible p).maximalIdeal_eq)).trans WittVector.quotientPEquiv

def ClusterCondition (p : ℕ) [Fact p.Prime] (s : ℚ) : Prop :=
  ∃ (ρ : WittRing p), ρ^2 = -3 ∧ ∃ (A : Finset (Fin 2)) (m : ℕ),
    Nonempty (FibreData p s.num s.den (twist s) ρ A m)

def HasGL2Type (B : GroupScheme ℚ) (g : ℕ) : Prop :=
  ∃ (E : Type) (_ : Field E) (_ : NumberField E), Module.finrank ℚ E = g ∧
    Nonempty (E →ₐ[ℚ] (ℚ ⊗[ℤ] End B))

def GoodWitt (k : Subfield (Residues p)) (A : GroupScheme (FractionRing (WittVector p k))) : Prop :=
  ∃ M : GroupScheme (WittVector p k), IsAbelianScheme M ∧
    Nonempty ((baseChange (algebraMap (WittVector p k) (FractionRing (WittVector p k)))).obj M ≅ A)

def InvariantCharts.Represents (P : InvariantCharts K n m) (z : Fin n → K) (r : ℚ) : Prop :=
  ∃ i, (P.equation i 1).eval z ≠ 0 ∧
    (r:K) = (P.equation i 0).eval z / (P.equation i 1).eval z

private lemma res_sextic (U V : K) (hV : V ≠ 0) :
    resultant (sextic U V) (sextic U V).derivative 6 5 =
      -(2:K)^22*3^6*U^2*V^3*(U-V)^6 := by

def twistPrimes (s : ℚ) : Finset ℕ :=
  let n := (branchInteger s).natAbs
  n.primeFactors.filter fun p => 3 < p ∧ n.factorization p % 4 = 2

private def integralSum (S : Finset (Fin 16)) : Bool :=
  decide (bitSum S 0 % 2 = 0 ∧ bitSum S 1 % 2 = 0 ∧
    bitSum S 2 % 2 = 0 ∧ bitSum S 3 % 2 = 0)

private theorem subset_mean (a : Fin 16 → ℝ) (ha : ∀ i, 0 ≤ a i)
    (S : Finset (Fin 16)) {n : ℕ} (hS : S.card = n) (hn : 0<n) :
    ∏ i ∈ S, a i ≤ ((∑ i, a i)/(n : ℝ))^n := by

private theorem product_scale {E : Type*} [Field E] (u : E) (x : Fin 16 → E)
    (S : Finset (Fin 16)) (n : ℕ) :
    (∏ i ∈ S, (u*x i)^n) = u^(n*S.card)*(∏ i ∈ S, x i ^ n) := by
